  "kind": "example",
  "source": "# writ.yaml for CI — headless posture (spec §14, Phase 2).\n# No human at the keyboard: `ask` fails closed on timeout or routes to an\n# out-of-band approver. Content capture stays off; the ledger + signed run\n# receipt are the audit artifact.\nversion: 1\ndefault: ask\n\nrules:\n  - id: block-destructive-shell\n    when: tool == \"bash\" and command matches \"rm -rf|mkfs|dd if=|:\\(\\)\\{\"\n    verdict: deny\n    reason: \"Destructive system command. Narrow the path and retry.\"\n\n  - id: protect-production-db\n    when: tool startswith \"postgres\" and query matches \"(?i)(DROP|TRUNCATE|ALTER)\"\n    verdict: ask\n    irreversible: true\n    timeout: 2m                       # short: CI minutes cost money\n\n  - id: egress-allowlist\n    when: tool == \"http\" and not url.host in hosts.allowed\n    verdict: deny\n    reason: \"CI egress is allow-listed. Add the host to hosts.allowed with a justification comment.\"\n\n  - id: never-read-secrets\n    when: path matches \"\\\\.env|id_rsa|\\\\.pem$|credentials$\"\n    verdict: deny\n    reason: \"Secrets are injected at dispatch; the agent never reads them.\"\n\n  - id: unverified-server-asks\n    when: server.trust == \"unverified\"\n    verdict: ask\n    reason: \"This MCP server has no trust verdict from the scanner.\"\n\nhosts:\n  allowed: [api.github.com, registry.npmjs.org, crates.io]\n"
